def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return {"value": None, "trace": {"old": old, "new": new, "output_meta": {"currency": None, "scale": None, "unit": "percentage"}}}
    change = new - old
    value = change / old * 100
    return {
        "value": value,
        "trace": {
            "old": old,
            "new": new,
            "change": change,
            "change_ratio": change / old,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"}
        }
    }
